animations.fade-in:
return new Promise(resolve => {
  gsap.fromTo(targetEl,
    { opacity: 0 },
    { opacity: 1, duration: 1, onComplete: resolve }
  );
});

animations.wipe-right:
return new Promise(resolve => {
  gsap.fromTo(targetEl,
    { opacity: 0, x: -20 },
    { opacity: 1, x: 0, duration: 0.6, ease: 'power2.out', onComplete: resolve }
  );
});

animations.scale-in:
return new Promise(resolve => {
  gsap.fromTo(targetEl,
    { opacity: 0, scale: 0.5 },
    { opacity: 1, scale: 1, duration: 0.5, ease: 'back.out(1.7)', onComplete: resolve }
  );
});

animations.bounce-in:
return new Promise(resolve => {
  gsap.fromTo(targetEl,
    { opacity: 0, y: -20, scale: 0.8 },
    {
      opacity: 1,
      y: 0,
      scale: 1,
      duration: 0.8,
      ease: 'elastic.out(1, 0.5)',
      onComplete: resolve
    }
  );
});

animations.slide-in-bottom:
return new Promise(resolve => {
  gsap.fromTo(targetEl,
    { opacity: 0, y: 20 },
    { opacity: 1, y: 0, duration: 0.5, ease: 'power2.out', onComplete: resolve }
  );
});

animations.rotate-in:
return new Promise(resolve => {
  gsap.fromTo(targetEl,
    { opacity: 0, rotation: -90, scale: 0.5 },
    { opacity: 1, rotation: 0, scale: 1, duration: 0.7, ease: 'back.out(1.5)', onComplete: resolve }
  );
});

animations.pulse:
return new Promise(resolve => {
  gsap.fromTo(targetEl,
    { opacity: 0, scale: 0.8 },
    {
      opacity: 1,
      scale: 1,
      duration: 0.6,
      ease: 'power2.out',
      onComplete: () => {
        gsap.to(targetEl, {
          scale: 1.1,
          duration: 0.3,
          yoyo: true,
          repeat: 1,
          ease: 'sine.inOut',
          onComplete: resolve
        });
      }
    }
  );
});
